mapper.insert:
INSERT INTO TB_IF_CHANGE_LOG_PILOT (
  LOG_ID, TARGET_TYPE_CD, TARGET_ID, ACTION_CD, BEFORE_JSON, AFTER_JSON, CHANGED_BY, CHANGED_AT, REMARK
) VALUES (
  #{logId}, #{targetTypeCd}, #{targetId}, #{actionCd}, #{beforeJson}, #{afterJson}, #{changedBy}, #{changedAt}, #{remark}
)

mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.TARGET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ACTION_CD,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.TARGET_TYPE_CD = #{targetTypeCd}
AND T1.TARGET_ID = #{targetId}
AND T1.ACTION_CD = #{actionCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.LOG_ID AS LOG_ID, T1.TARGET_TYPE_CD AS TARGET_TYPE_CD, T1.TARGET_ID AS TARGET_ID,
           T1.ACTION_CD AS ACTION_CD, T1.BEFORE_JSON AS BEFORE_JSON, T1.AFTER_JSON AS AFTER_JSON,
           T1.CHANGED_BY AS CHANGED_BY, T1.CHANGED_AT AS CHANGED_AT, T1.REMARK AS REMARK
      FROM TB_IF_CHANGE_LOG_PILOT T1

     ORDER BY T1.CHANGED_AT DESC, T1.LOG_ID DESC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_EVIDENCE_FILE_PILOT (
  EVIDENCE_ID, TARGET_TYPE_CD, TARGET_ID, GATE_ID, FILE_NAME, FILE_URI, URL, UPLOADED_BY, UPLOADED_AT, REMARK
) VALUES (
  #{evidenceId}, #{targetTypeCd}, #{targetId}, #{gateId}, #{fileName}, #{fileUri}, #{url}, #{uploadedBy}, #{uploadedAt}, #{remark}
)

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.EVIDENCE_ID AS EVIDENCE_ID, T1.TARGET_TYPE_CD AS TARGET_TYPE_CD, T1.TARGET_ID AS TARGET_ID,
           T1.GATE_ID AS GATE_ID, T1.FILE_NAME AS FILE_NAME, T1.FILE_URI AS FILE_URI, T1.URL AS URL,
           T1.UPLOADED_BY AS UPLOADED_BY, T1.UPLOADED_AT AS UPLOADED_AT, T1.REMARK AS REMARK
      FROM TB_IF_EVIDENCE_FILE_PILOT T1

     ORDER BY T1.UPLOADED_AT DESC, T1.EVIDENCE_ID DESC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
